CREATE TABLE IF NOT EXISTS student_knowledge_model_state(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,course_id BIGINT UNSIGNED NOT NULL,model_version VARCHAR(64) NOT NULL,knowledge_index_version VARCHAR(64) NOT NULL,state_ref VARCHAR(255) NOT NULL,processed_through_seq BIGINT UNSIGNED NOT NULL,status VARCHAR(24) NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_student_model_state(user_id,course_id),KEY idx_model_state_version(model_version,knowledge_index_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS knowledge_model_rollout_policy(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,course_id BIGINT UNSIGNED NULL,model_version VARCHAR(64) NOT NULL,knowledge_index_version VARCHAR(64) NOT NULL,rollout_percent DECIMAL(6,4) NOT NULL DEFAULT 0,enabled TINYINT NOT NULL DEFAULT 0,fallback_algorithm VARCHAR(64) NOT NULL,config_json JSON NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_model_rollout(course_id,model_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
